// ============================================================================
// E158（择根与修复四岔路） 第 3 次跑的臂（`research/prompts/e158-r3-prereg.md` 5.1、5.2）：只在草稿副本里套用，不进 crates/。
// 判据 N（有一条比所选那一版新的根、这一次读不出）与 N 判真之后的处置，外加代码审阅第 22 条那一格的处置。
// ============================================================================

/// 这一臂的判据 N 用哪一样（登记 5.1）。
#[derive(Clone, Copy, Debug, PartialEq, Eq)]
pub enum R3NewerRootWitness {
    /// N-配置（与 N-配置续）：池里全部自证系统配置槽的 journal tail 最大值 > 所选那一版那次发布的末条记录计数器。
    SystemConfigurationTail,
    /// N-槽：择根那一遍有一个根环槽读错（`BadRootRingSlotReading::Unreadable`）。
    UnreadableRootRingSlot,
}

/// N 判真之后这一臂怎么做（登记 5.2）。
#[derive(Clone, Copy, Debug, PartialEq, Eq)]
pub enum R3WhenNewerRootWitnessed {
    /// 甲：拒可写。
    RefuseWritable,
    /// 乙：等一个间隔、在读缓存上重做读阶段，最多 R 轮，仍真再拒。
    RereadThenRefuse,
    /// 丙：从同一条所选根起再扫一遍、再重放一遍，走到见证就用它，走不到再拒。
    RebuildFromRecordsThenRefuse,
}

const R3_ARM_WITNESS: R3NewerRootWitness = E158_R3_ARM_WITNESS_NOT_SET;
const R3_ARM_WHEN_WITNESSED: R3WhenNewerRootWitnessed = E158_R3_ARM_WHEN_WITNESSED_NOT_SET;
/// 乙 的重读轮数 R（登记「读法写死」：D16（发布语义） 已定项 1「根槽这一次读坏」那一行的「重读一次」）。
const R3_REREAD_ROUNDS: u32 = 1;
/// 产品路径「等一个间隔」睡多久（副本里装置恒装钩子，这个值不会被用到）。
const R3_PRODUCT_WAIT_MILLISECONDS: u64 = 100;

/// 这一臂在一次可写挂载里判了什么（装置读，跨臂对拍用）。
#[derive(Clone, Debug, Default, PartialEq, Eq)]
pub struct R3MountObservation {
    pub witness_judged: bool,
    pub newer_root_on_the_first_pass: bool,
    pub witnessed_tail: u64,
    pub selected_version_last_counter: Option<u64>,
    pub undecidable: bool,
    pub unreadable_ring_slots_on_the_first_pass: u64,
    pub reread_rounds: u32,
    pub rebuilt_from_records: bool,
    pub shadow_ledger_table_unreadable_on_the_first_read: bool,
    pub shadow_ledger_table_rereads: u32,
}

thread_local! {
    static R3_OBSERVATION: std::cell::RefCell<R3MountObservation> =
        std::cell::RefCell::new(R3MountObservation::default());
    static R3_WAIT_HOOK: std::cell::RefCell<Option<Box<dyn Fn()>>> =
        const { std::cell::RefCell::new(None) };
}

/// 装「等一个间隔」的钩子（只供测试：装置换成推进虚拟时钟）；`None` 恢复产品路径的睡眠。
pub fn r3_install_wait_hook(hook: Option<Box<dyn Fn()>>) {
    R3_WAIT_HOOK.with(|slot| *slot.borrow_mut() = hook);
}

/// 取走这个线程上最近一次可写挂载的观测。
pub fn r3_take_observation() -> R3MountObservation {
    R3_OBSERVATION.with(|observation| std::mem::take(&mut *observation.borrow_mut()))
}

fn r3_observe(update: impl FnOnce(&mut R3MountObservation)) {
    R3_OBSERVATION.with(|observation| update(&mut observation.borrow_mut()));
}

fn r3_wait_an_interval() {
    let hooked = R3_WAIT_HOOK.with(|slot| slot.borrow().as_ref().map(|hook| hook()).is_some());
    if !hooked {
        std::thread::sleep(std::time::Duration::from_millis(R3_PRODUCT_WAIT_MILLISECONDS));
    }
}

/// 这次挂载内有效的读缓存（乙）：只记读成的落点的字节，读失败的不记。
struct R3ReadCache<'reader> {
    reader: &'reader dyn PoolReader,
    cached: std::cell::RefCell<BTreeMap<(DeviceIdentity, u64, usize), Vec<u8>>>,
}

impl PoolReader for R3ReadCache<'_> {
    fn device_identities(&self) -> Vec<DeviceIdentity> {
        self.reader.device_identities()
    }
    fn device_size_in_bytes(&self, device: DeviceIdentity) -> Option<u64> {
        self.reader.device_size_in_bytes(device)
    }
    fn read(
        &self,
        device: DeviceIdentity,
        offset: crate::address::DeviceOffsetInBytes,
        length: usize,
    ) -> Option<Vec<u8>> {
        let key = (device, offset.0, length);
        if let Some(bytes) = self.cached.borrow().get(&key) {
            return Some(bytes.clone());
        }
        let bytes = self.reader.read(device, offset, length)?;
        self.cached.borrow_mut().insert(key, bytes.clone());
        Some(bytes)
    }
    fn journal_record_offsets_hint(
        &self,
        device: DeviceIdentity,
        ring_start: crate::address::DeviceOffsetInBytes,
        ring_bytes: u64,
    ) -> Option<Vec<crate::address::DeviceOffsetInBytes>> {
        self.reader
            .journal_record_offsets_hint(device, ring_start, ring_bytes)
    }
}

/// 读阶段（择根、扫 journal、重放）交回的东西，外加择根那一遍读错的根环槽个数（N-槽）。
struct R3ReadPhase {
    chosen_root: RootRecord,
    records: BTreeMap<(InstanceGeneration, u64), crate::journal::JournalRecord>,
    journal: JournalScanReport,
    effective_root: RootRecord,
    unreadable_ring_slots: u64,
}

/// 与 `choose_root`、`scan_journal`、`replay_journal(…, true)` 同一串读（择根按同一个槽序读每个槽一次），另数读错的槽。
fn r3_read_phase(
    reader: &dyn PoolReader,
    system_configuration: &crate::system_configuration::SystemConfiguration,
) -> Result<R3ReadPhase, MountError> {
    let mut best: Option<RootRecord> = None;
    let mut unreadable_ring_slots = 0u64;
    for ring_slot in every_root_ring_slot(&system_configuration.immutable.sizes) {
        match read_root_ring_slot(
            reader,
            &system_configuration.immutable.region_devices,
            &system_configuration.immutable.sizes,
            &system_configuration.immutable.filesystem_identifier,
            ring_slot,
        ) {
            RootRingSlotReading::SelfVerified(candidate) => {
                let candidate_key = (candidate.checkpoint_txg, candidate.instance);
                if best.is_none_or(|current| {
                    candidate_key > (current.checkpoint_txg, current.instance)
                }) {
                    best = Some(candidate);
                }
            }
            RootRingSlotReading::Bad(BadRootRingSlotReading::Unreadable) => {
                unreadable_ring_slots += 1;
            }
            RootRingSlotReading::Bad(BadRootRingSlotReading::NotSelfVerified) => {}
        }
    }
    let chosen_root = best.ok_or(RecoveryFailure::NoValidRoot)?;
    let records = scan_journal(reader, system_configuration);
    let (journal, effective_root) = replay_journal(
        reader,
        &chosen_root,
        system_configuration.immutable.sizes.journal_ring_bytes,
        &records,
        true,
    )?;
    Ok(R3ReadPhase {
        chosen_root,
        records,
        journal,
        effective_root,
        unreadable_ring_slots,
    })
}

/// 判据 N 在一遍读阶段上的判定。
struct R3Judgement {
    newer: bool,
    witnessed_tail: u64,
    selected_version_last_counter: Option<u64>,
    undecidable: bool,
    unreadable_ring_slots: u64,
}

impl R3Judgement {
    fn refusal(&self, rounds: u32) -> MountError {
        match R3_ARM_WITNESS {
            R3NewerRootWitness::SystemConfigurationTail => {
                MountError::R3NewerRootWitnessedByTheSystemConfiguration {
                    witnessed_tail: self.witnessed_tail,
                    selected_version_last_counter: self.selected_version_last_counter,
                    undecidable: self.undecidable,
                    rounds,
                }
            }
            R3NewerRootWitness::UnreadableRootRingSlot => MountError::R3UnreadableRootRingSlot {
                unreadable_ring_slots: self.unreadable_ring_slots,
                rounds,
            },
        }
    }
}

/// N-配置（登记 5.1 第一行）：c_见证 = 每块盘两槽里全部自证系统配置槽的 journal tail 的最大值（没有或为 0 ⇒ 假）；
/// 所选那一版那次发布带末条标志的记录读得出 ⇒ c_见证 > 它的计数器；读不出而计数器等于 c_见证 的记录读得出 ⇒ 那条记录的
/// (实例代号, checkpoint_txg) > 所选那一版的；两条都读不出 ⇒ 判不出，按真处置。
fn r3_system_configuration_judgement(
    reader: &dyn PoolReader,
    system_configuration: &crate::system_configuration::SystemConfiguration,
    records: &BTreeMap<(InstanceGeneration, u64), crate::journal::JournalRecord>,
    effective_root: &RootRecord,
) -> (bool, u64, Option<u64>, bool) {
    let spacing = u64::from(
        system_configuration
            .immutable
            .sizes
            .fixed_structure_slot_spacing,
    );
    let witnessed_tail = reader
        .device_identities()
        .into_iter()
        .flat_map(|device| {
            verified_system_configuration_slots(
                reader,
                device,
                spacing,
                &system_configuration.immutable.filesystem_identifier,
            )
        })
        .map(|slot| slot.quantities.journal_tail)
        .max()
        .unwrap_or(0);
    let selected_version_last_counter = records
        .values()
        .filter(|record| {
            record.instance == effective_root.instance
                && record.checkpoint_txg == effective_root.checkpoint_txg
                && record.place_in_publish
                    == crate::journal::JournalRecordPlaceInPublish::LastRecordOfThePublish
        })
        .map(|record| record.counter)
        .max();
    if witnessed_tail == 0 {
        return (false, witnessed_tail, selected_version_last_counter, false);
    }
    if let Some(counter) = selected_version_last_counter {
        return (
            witnessed_tail > counter,
            witnessed_tail,
            selected_version_last_counter,
            false,
        );
    }
    match records
        .values()
        .find(|record| record.counter == witnessed_tail)
    {
        Some(witness_record) => (
            (witness_record.instance, witness_record.checkpoint_txg)
                > (effective_root.instance, effective_root.checkpoint_txg),
            witnessed_tail,
            None,
            false,
        ),
        None => (true, witnessed_tail, None, true),
    }
}

fn r3_judge(
    reader: &dyn PoolReader,
    system_configuration: &crate::system_configuration::SystemConfiguration,
    phase: &R3ReadPhase,
) -> R3Judgement {
    match R3_ARM_WITNESS {
        R3NewerRootWitness::SystemConfigurationTail => {
            let (newer, witnessed_tail, selected_version_last_counter, undecidable) =
                r3_system_configuration_judgement(
                    reader,
                    system_configuration,
                    &phase.records,
                    &phase.effective_root,
                );
            R3Judgement {
                newer,
                witnessed_tail,
                selected_version_last_counter,
                undecidable,
                unreadable_ring_slots: phase.unreadable_ring_slots,
            }
        }
        R3NewerRootWitness::UnreadableRootRingSlot => R3Judgement {
            newer: phase.unreadable_ring_slots > 0,
            witnessed_tail: 0,
            selected_version_last_counter: None,
            undecidable: false,
            unreadable_ring_slots: phase.unreadable_ring_slots,
        },
    }
}

fn r3_observe_first_pass(judgement: &R3Judgement) {
    r3_observe(|observation| {
        observation.witness_judged = true;
        observation.newer_root_on_the_first_pass = judgement.newer;
        observation.witnessed_tail = judgement.witnessed_tail;
        observation.selected_version_last_counter = judgement.selected_version_last_counter;
        observation.undecidable = judgement.undecidable;
        observation.unreadable_ring_slots_on_the_first_pass = judgement.unreadable_ring_slots;
    });
}

/// 这一臂的读阶段：在 `replay_journal` 交回之后、`rebuild_previous_version` 之前判 N（登记 5.1 末），按臂的处置走。
fn r3_read_phase_of_this_arm(
    reader: &dyn PoolReader,
    system_configuration: &crate::system_configuration::SystemConfiguration,
) -> Result<R3ReadPhase, MountError> {
    r3_observe(|observation| *observation = R3MountObservation::default());
    match R3_ARM_WHEN_WITNESSED {
        R3WhenNewerRootWitnessed::RefuseWritable => {
            let phase = r3_read_phase(reader, system_configuration)?;
            let judgement = r3_judge(reader, system_configuration, &phase);
            r3_observe_first_pass(&judgement);
            if judgement.newer {
                return Err(judgement.refusal(0));
            }
            Ok(phase)
        }
        R3WhenNewerRootWitnessed::RereadThenRefuse => {
            let cache = R3ReadCache {
                reader,
                cached: std::cell::RefCell::new(BTreeMap::new()),
            };
            let mut round = 0u32;
            loop {
                let phase = r3_read_phase(&cache, system_configuration)?;
                let judgement = r3_judge(reader, system_configuration, &phase);
                if round == 0 {
                    r3_observe_first_pass(&judgement);
                }
                r3_observe(|observation| observation.reread_rounds = round);
                if !judgement.newer {
                    return Ok(phase);
                }
                if round == R3_REREAD_ROUNDS {
                    return Err(judgement.refusal(round));
                }
                r3_wait_an_interval();
                round += 1;
            }
        }
        R3WhenNewerRootWitnessed::RebuildFromRecordsThenRefuse => {
            let phase = r3_read_phase(reader, system_configuration)?;
            let judgement = r3_judge(reader, system_configuration, &phase);
            r3_observe_first_pass(&judgement);
            if !judgement.newer {
                return Ok(phase);
            }
            r3_observe(|observation| observation.rebuilt_from_records = true);
            let records = scan_journal(reader, system_configuration);
            let (journal, effective_root) = replay_journal(
                reader,
                &phase.chosen_root,
                system_configuration.immutable.sizes.journal_ring_bytes,
                &records,
                true,
            )?;
            let rebuilt_version_last_counter = records
                .values()
                .filter(|record| {
                    record.instance == effective_root.instance
                        && record.checkpoint_txg == effective_root.checkpoint_txg
                })
                .map(|record| record.counter)
                .max();
            if rebuilt_version_last_counter.is_some_and(|counter| counter >= judgement.witnessed_tail)
            {
                return Ok(R3ReadPhase {
                    chosen_root: phase.chosen_root,
                    records,
                    journal,
                    effective_root,
                    unreadable_ring_slots: phase.unreadable_ring_slots,
                });
            }
            Err(MountError::R3RebuildFromRecordsStoppedBelowTheWitness {
                witnessed_tail: judgement.witnessed_tail,
                rebuilt_version_last_counter,
            })
        }
    }
}

/// 代码审阅第 22 条那一格（`rebuilt_allocator` 里第二次读实例表）按臂处置：甲 读不出就拒；乙 等一个间隔重读最多 R 轮、仍读不出再拒；
/// 丙 不读第二次，用 `rebuild_previous_version` 读出的那一张。
#[allow(
    clippy::ptr_arg,
    reason = "choose_root 走 &dyn PoolReader，要一个有大小的读者：Vec 实现了它、切片不能转成 dyn"
)]
fn r3_newest_table_for_the_shadow_ledger<Device: BlockDevice>(
    devices: &Vec<(DeviceIdentity, Device)>,
    system_configuration: &crate::system_configuration::SystemConfiguration,
    previous: &PreviousVersion,
) -> Result<Option<InstanceTableRecords>, MountError> {
    match R3_ARM_WHEN_WITNESSED {
        R3WhenNewerRootWitnessed::RebuildFromRecordsThenRefuse => {
            Ok(Some(previous.instance_table_chain().records.clone()))
        }
        R3WhenNewerRootWitnessed::RefuseWritable => {
            match choose_root(devices, system_configuration)
                .and_then(|newest| instance_table_of_root(devices, &newest))
            {
                Some(table) => Ok(Some(table)),
                None => {
                    r3_observe(|observation| {
                        observation.shadow_ledger_table_unreadable_on_the_first_read = true;
                    });
                    Err(MountError::R3NewestInstanceTableUnreadableForTheShadowLedger { rounds: 0 })
                }
            }
        }
        R3WhenNewerRootWitnessed::RereadThenRefuse => {
            let mut newest = choose_root(devices, system_configuration);
            let mut round = 0u32;
            loop {
                if let Some(table) = newest
                    .as_ref()
                    .and_then(|root| instance_table_of_root(devices, root))
                {
                    r3_observe(|observation| observation.shadow_ledger_table_rereads = round);
                    return Ok(Some(table));
                }
                if round == 0 {
                    r3_observe(|observation| {
                        observation.shadow_ledger_table_unreadable_on_the_first_read = true;
                    });
                }
                if round == R3_REREAD_ROUNDS {
                    r3_observe(|observation| observation.shadow_ledger_table_rereads = round);
                    return Err(
                        MountError::R3NewestInstanceTableUnreadableForTheShadowLedger { rounds: round },
                    );
                }
                r3_wait_an_interval();
                round += 1;
                if newest.is_none() {
                    newest = choose_root(devices, system_configuration);
                }
            }
        }
    }
}

/// 管理员回退没做成（D23（journal 的角色与格式） 已定项 14「在任何写之前拒」那一格与候选集）。成员按管理员要做的决定分：

